import CreateCustomer from "./CreateCustomer";

export default function Home() {
  return (
    <div className="container">
      {/* Company Introduction Section */}
      <div className="text-center my-5">
        <h1 className="display-4">Welcome to EnergyTech.ai</h1>
        <p className="lead">
          EnergyTech.ai is a cutting-edge energy management company,
          providing smart solutions to track and manage energy consumption efficiently.
        </p>
        <p>
          This platform allows managing customers and their addresses efficiently.
        </p>
      </div>

      <hr />

      {/* Add Customer Form directly below */}
      <div className="my-5">
        <h2 className="mb-3 text-center">Add New Customer</h2>
        <CreateCustomer />
      </div>
    </div>
  );
}
